 form_type: 'Type', form_text: 'Your text', form_file: 'Photo or document (optional, 2 MB max)', form_mail: 'Email to get an answer (optional)', form_consent: 'I agree that my email is kept to answer me, then deleted.', form_nopub: 'Nothing is published directly: a reviewer checks first.', form_send: 'Send', form_back: 'Back to the record', form_prefill: 'My grandmother was part of this group of women from Rennes in 1944. I kept a letter from her.', form_toobig: 'The file is too large (2 MB max).',
