 st: { 'en attente': 'pending', spam: 'spam', doublon: 'duplicate', 'publiée': 'published', 'refusée': 'refused' },
 hist_title: 'The history of the place', hist_lead: 'A fort built to defend Paris, which became a place of imprisonment during the Second World War.',
 hist_fort_h: 'The Fort de Romainville', hist_fort_p: 'The fort is in Les Lilas, in Seine-Saint-Denis. It is one of the forts built around Paris in the 19th century.',
 hist_war_h: '1940 – 1944', hist_war_p: 'During the German occupation, the fort became a place of internment and transit. Resistance members, hostages and deportees passed through it. Many women waited there before leaving for the Ravensbrück camp.',
 hist_cas_h: 'Casemate no. 17', hist_cas_p: 'On the walls, the people held there left messages: names, dates, words of hope, often in pencil. These traces are fragile and hard to see.',
 hist_1718_h: 'The “17 18” message', hist_1718_p: 'On one wall, the number 17 is crossed out and 18 is written above it. A group of women from the Resistance, brought from Rennes, was due to leave for Ravensbrück on the 17th; the departure was delayed by one day.',
 hist_today_h: 'Today', hist_today_p: 'The fort is a place of memory. The lamp of memory aims to help people read these traces without damaging or distorting them.',
 hist_note: 'These texts are simplified. In a public version, they would be written and reviewed by historians.',
 how_title: 'How it works', how_lead: 'Anyone can contribute. Nothing is published without review.',
 how_v_h: 'For the visitor', how_v: ['They light up the wall with a finger or the mouse.', 'They open the record of a message.', 'They read or listen to its story, in their language.', 'They see the truth label.'],
 how_c_h: 'The journey of a contribution', how_c: ['A visitor or a family sends information.', 'The server saves it with the status “pending”.', 'It finds the language and the keywords (places, dates, people).', 'It sets spam aside and groups duplicates.', 'It chooses the reviewer whose specialities match best.', 'The reviewer checks, corrects or refuses. If approved, the record is published with a label.'],
 how_rule_h: 'How the reviewer is chosen', how_rule: ['For each available reviewer who reads the language of the text:', 'score = number of keywords shared with their specialities', '+1 if they read a language other than French', '+1 for an archivist if it is a document', 'The best score wins; if tied, the one with the least work.', 'If nobody matches: the memorial’s referent.'],
 how_roles_h: 'Roles', how_role_th: ['Role', 'What they can do'], how_roles: [['Visitor', 'Light up the wall, read and listen to records, change language'], ['Contributor', 'Add a comment, a correction, a memory or a document'], ['Moderator', 'First sorting: spam, duplicates, simple requests'], ['Historian', 'Approve, correct, refuse or ask for more information'], ['Archivist', 'Check photos, letters and documents'], ['Administrator', 'Manage reviewers and follow the log']],
 how_many_h: 'What if there are 1,000 contributions?', how_many_p: 'Spam is set aside automatically, duplicates are grouped, documents come first, and the work is shared between reviewers. Each reviewer gets a single summary email per day.',
 proj_title: 'The project', proj_lead: 'A Master’s project at Université Paris 8, on digital memorials.',
 proj_d_h: 'Our approach', proj_d: ['Information and technology watch on digital memorials.', 'Choice of a concept: reveal rather than show.', 'Functional and technical specifications, use scenarios.', 'Prototype, then a full website with a server and a database.', 'Tests by group members who did not build the site.'],
 proj_t_h: 'Technical choices', proj_t: ['Front-end: HTML, CSS and JavaScript, no framework, for a light and lasting site.', 'Back-end: Node.js server and SQLite database, with no external dependency.', 'Protected accounts for historians (hashed passwords, secure session).', 'Accessibility following the RGAA and four languages, including right-to-left Arabic.', 'No personal data from visitors is kept, except an optional email.'],
 proj_e_h: 'What we did not invent', proj_e_p: 'The “17 18” message is real. The other messages on the wall, the characters in the scenarios and the reviewers are fictional, to show how it works.',
 a11y_title: 'Accessibility statement', a11y_state: 'Status: partially compliant with RGAA 4.1 (self-assessment by the team, not yet audited by an expert).',
 a11y_done_h: 'What we did', a11y_done: ['Images: the wall has a description and every message exists in a text version.', 'Colours: contrasted text; labels always have text, not only a colour; “High contrast” button.', 'Multimedia: every record can be listened to and its text stays on screen.', 'Forms: every field has a label; optional fields are marked.', 'Navigation: “Skip to content” link, keyboard menu, visible focus; Escape closes the record.', 'Keyboard: the lamp moves with the arrows; no action requires a mouse.', 'Presentation: text enlarged up to 200% (A− / A+), layout adapted to phones.', 'Languages: the page language is declared; Arabic is shown right to left.', 'Motion: animations stop if the device asks for reduced motion.'],
 a11y_lim_h: 'Known limits', a11y_lim: ['The lamp effect is visual: the alternative is the text version.', 'Voice reading depends on the browser.'],
 legal_title: 'Legal notice and personal data', legal_ed_h: 'Publisher', legal_ed_p: 'Student project made as part of a Master’s degree at Université Paris 8. Demonstration site, non-commercial.',
 legal_data_h: 'Personal data (GDPR)', legal_data: ['Visitors have no account and are not tracked: no advertising, no audience measurement.', 'A contribution contains the text sent and, if you choose, a file and an email.', 'The email is only used to answer you. It is never published and is deleted after the answer.', 'You can ask for your contribution to be deleted at any time.'],
 legal_cookie_h: 'Cookies', legal_cookie_p: 'A single technical cookie, for logged-in historians. Display preferences (language, text size) stay in your browser.',
 h_title: 'Historian area', h_login: 'Log in', h_id: 'Username', h_pass: 'Password', h_enter: 'Log in', h_demo: 'For testing: demo accounts durand, benali, keller, rossi or admin (password memoire2026), or create your own account.', h_bad: 'Wrong username or password.', h_hello: 'Logged in:', h_logout: 'Log out', h_admin: 'Administration',
