 h_queue: 'Por verificar', h_empty: 'Nada que verificar por ahora.', h_prio: 'Prioridad', h_why: '¿Por qué tú?', h_dups: 'duplicado(s) agrupado(s)', h_file: 'Ver el archivo', h_validate: 'Aprobar', h_edit: 'Corregir', h_more: 'Pedir más', h_refuse: 'Rechazar', h_save: 'Guardar y aprobar', h_reason: 'Motivo del rechazo', h_confirm: 'Confirmar el rechazo', h_question: 'Tu pregunta al contribuidor', h_ask: 'Enviar la pregunta', h_done_ok: 'Publicada con su etiqueta.', h_done_no: 'Rechazada: no se publicará.', h_done_ask: 'Pregunta enviada.', h_noemail: 'No dejó correo: la petición queda en el registro.', h_msg: 'mensaje', h_type: 'tipo', h_label: 'Etiqueta',
 ad_title: 'Administración', ad_lead: 'Cada validador se guarda con variables. El servidor compara las palabras clave de cada contribución con estas variables.', ad_vals: 'Los validadores', ad_th: ['Nombre', 'Rol', 'Especialidades', 'Idiomas', 'Disponible', 'Por tratar'], ad_add: 'Añadir un validador', ad_name: 'Nombre', ad_spec: 'Especialidades (separadas por comas)', ad_langs: 'Idiomas (fr, en, es, ar…)', ad_role: 'Rol', ad_yes: 'sí', ad_no: 'no',
 ad_stats: 'Las contribuciones', ad_journal: 'Registro', ad_outbox: 'Correos preparados', ad_digest: 'Preparar el resumen del día', ad_sim: 'Simular 1000 contribuciones', ad_sim_res: ['Spam descartado', 'Duplicados agrupados', 'Por verificar', 'de ellas prioritarias'], ad_split: 'Reparto entre los validadores', ad_ms: 'Procesado en', ad_need: 'Solo para el administrador.',
